import { businessConfig } from '../config/business.config';

/**
 * Builds a wa.me chat URL with a URL-encoded, pre-filled message.
 * Security: user-supplied text is always passed through encodeURIComponent,
 * so it cannot alter the URL structure.
 */
export function whatsappUrl(message: string = businessConfig.whatsappDefaultMessage): string {
  return `https://wa.me/${businessConfig.whatsapp}?text=${encodeURIComponent(message)}`;
}

/** Builds the WhatsApp enquiry message for a specific service. */
export function serviceEnquiryMessage(serviceName: string): string {
  return `Hi! I'm interested in your ${serviceName} service in ${businessConfig.locality}. Could you please share the details and availability?`;
}

/** Returns the tel: link used to open the phone dialer. */
export function telUrl(): string {
  return `tel:${businessConfig.phone}`;
}

/** Returns a mailto: link, or an empty string when no email is configured. */
export function mailtoUrl(): string {
  return businessConfig.email ? `mailto:${businessConfig.email}` : '';
}

/**
 * Opens an external URL in a new tab without giving the new page access to window.opener.
 * Security: 'noopener,noreferrer' prevents reverse-tabnabbing.
 */
export function openExternal(url: string): void {
  window.open(url, '_blank', 'noopener,noreferrer');
}
